	}
	rng := rand.New(rand.NewPCG(req.Seed, 0x4833))
	for _, m := range []struct {
		dst, inj []float32
	}{{video.Data[:nc], req.CondNoise}, {video.Data[nc:], req.VideoNoise}, {audio.Data, req.AudioNoise}} {
		if m.inj != nil {
			if len(m.inj) != len(m.dst) {
