	if err := g.layoutWeights(layers, bankBytes); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.allocActivations(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.build(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.stageWeights(set, layers); err != nil {
		g.Destroy()
		return nil, err
	}
	return g, nil
}

