func LoadWith(dir string, cfg *Config, layers int) (*Model, error) {
	if layers <= 0 || layers > cfg.NumLayers {
		return nil, fmt.Errorf("qwen: asked for %d of %d layers", layers, cfg.NumLayers)
	}
	set, err := safetensors.OpenSet(dir)
	if err != nil {
		return nil, err
	}
	defer set.Close()

	m := &Model{Cfg: cfg}
	if m.Rows, m.Embed, err = LoadEmbedding(set, cfg); err != nil {
		return nil, err
	}
	for i := 0; i < layers; i++ {
		l, err := LoadLayer(set, i, cfg)
		if err != nil {
			return nil, err
		}
		m.Layers = append(m.Layers, l)
	}
	return m, nil
}

// LoadEmbedding reads the token embedding table as float32, returning its row
// count alongside it -- vocab_size is padded above the tokenizer's id space,
// and the table is the authority on how far.
func LoadEmbedding(set *safetensors.Set, cfg *Config) (int, []float32, error) {
	l := &loader{set: set}
	name := cfg.Prefix + embedName
	shape := l.shape(name)
	if l.err != nil {
		return 0, nil, l.err
	}
	if len(shape) != 2 || shape[1] != cfg.HiddenSize {
		return 0, nil, fmt.Errorf("qwen: %s is %v, want [rows %d]", name, shape, cfg.HiddenSize)
	}
	data := l.f32(name)
	return shape[0], data, l.err
}

// LoadLayer reads one decoder layer as float32. It is what both the CPU
// model and the GPU encoder build from: the GPU path stages one layer at a
// time into its fp16 banks and drops it, so the host never holds more than
// the 404 MB one layer costs rather than the 14.1 GB all 35 would.
func LoadLayer(set *safetensors.Set, i int, cfg *Config) (*Layer, error) {
	l := &loader{set: set}
	p := fmt.Sprintf("%slayers.%d.", cfg.Prefix, i)
	layer := &Layer{
		AttnNorm: l.rms(p+"input_layernorm", cfg.RMSEps),
		Q:        l.linear(p + "self_attn.q_proj"),
		K:        l.linear(p + "self_attn.k_proj"),
		V:        l.linear(p + "self_attn.v_proj"),
		QNorm:    l.rms(p+"self_attn.q_norm", cfg.RMSEps),
		KNorm:    l.rms(p+"self_attn.k_norm", cfg.RMSEps),
		O:        l.linear(p + "self_attn.o_proj"),
		FFNNorm:  l.rms(p+"post_attention_layernorm", cfg.RMSEps),
		Gate:     l.linear(p + "mlp.gate_proj"),
		Up:       l.linear(p + "mlp.up_proj"),
		Down:     l.linear(p + "mlp.down_proj"),

		Heads:   cfg.NumHeads,
		KVHeads: cfg.NumKVHeads,
		HeadDim: cfg.HeadDim,
	}
	if l.err != nil {
		return nil, l.err
	}
	// The shapes are checked on every layer rather than on the first: a
	// checkpoint that changes width halfway through is not a thing that
	// happens, but a *name* that resolves to the wrong tensor is, and this is
	// where it would show.
	for _, c := range []struct {
		name      string
		got, want int
	}{
		{"q_proj", layer.Q.Out, cfg.NumHeads * cfg.HeadDim},
		{"k_proj", layer.K.Out, cfg.NumKVHeads * cfg.HeadDim},
		{"v_proj", layer.V.Out, cfg.NumKVHeads * cfg.HeadDim},
		{"o_proj", layer.O.Out, cfg.HiddenSize},
		{"gate_proj", layer.Gate.Out, cfg.IntermediateSize},
		{"up_proj", layer.Up.Out, cfg.IntermediateSize},
		{"down_proj", layer.Down.Out, cfg.HiddenSize},
	} {
		if c.got != c.want {
			return nil, fmt.Errorf("qwen: layer %d %s produces %d, want %d", i, c.name, c.got, c.want)
		}
	}
	return layer, nil
}

// embedName is the one tensor outside the layers that the encoder reads,
// under Config.Prefix. The final norm and the lm_head are in the checkpoint
// and are never loaded by *this* path: hidden_states[-2] is taken before
// either of them runs. An embedding model wants both and reads them itself
// (embed/load.go), which is why they are not here.
const embedName = "embed_tokens.weight"
	ropeAdjacent bool
	// noCausal uses the grouped-query build without the causal mask, i.e.
	// lets every token see the whole prompt.
	noCausal bool
	// qkNormWide norms q and k over the full width instead of per head.
	qkNormWide bool
	// wrongBLayout stages every weight row-major while the kernel reads
	// fragment tiles.
	wrongBLayout bool
	// shiftBank sends every layer's projections to the next bank at the same
	// offsets, so layer i reads layer i+1's weights -- the mistake a
	// per-bank descriptor set invites, and one that produces a perfectly
	// plausible tensor.
	shiftBank bool
}

// layerWeights is where one layer's weights sit in the arenas.
type layerWeights struct {
	// fp32 arena: the four norms.
	attnNorm, ffnNorm uint32
	qNorm, kNorm      uint32
	// fp16 bank and the offset of each projection inside it, in halves.
	// Under BankQ8 that is the shared scratch, the same for every layer.
	bank int
	bOff map[Proj]uint32
	// BankQ8: the int8 bank and each projection's byte offset in it. q8 is
	// false for a layer the bank keeps in fp16 (NewGPUEncoderMixed), which
	// then has fp16 offsets of its own and no expansion.
	q8    bool
	qbank int
	qOff  map[Proj]uint32
}

// GPUEncoder runs Qwen3 layers on the device. One instance holds every layer
// the pipeline needs -- 7.06 GB across two storage buffers -- so a prompt is
// a dispatch sequence and not a load.
type GPUEncoder struct {
	dev *vk.Device
	cfg *Config

	wbuf  *vk.Buffer
	abuf  *vk.Buffer
	hbuf  *vk.Buffer
	banks []*vk.Buffer
	// bank is how the projections are held. Under BankQ8, qbanks hold them
	// as int8 and banks is the one fp16 scratch a layer is expanded into
	// by its first seven dispatches (dequant, one pipeline per qbank).
	bank    Bank
	keep    map[int]bool // layers BankQ8 holds in fp16 instead
	qbanks  []*vk.Buffer
	dequant []*vk.ComputePipeline

	pipes map[string]*vk.ComputePipeline
	gemms []map[GEMMKernel]*vk.ComputePipeline
	mods  []*vk.ShaderModule

	// AutoPlan re-plans every run for its own length, using PlanFor. It is on
	// by default and it is free: every rung reads the same staged weight, so
	// this changes which pipeline a dispatch names and nothing else. Set it
	// false to hold a plan across lengths, which is what the ladder does.
	AutoPlan bool
func newEncoder(dev *vk.Device, set *safetensors.Set, cfg *Config, layers, maxTokens int, plan GEMMPlan, ctl controls, bankBytes int, bank Bank, keepFP16 []int) (*GPUEncoder, error) {
	explicitPlan := plan
	if layers <= 0 || layers > cfg.NumLayers {
		return nil, fmt.Errorf("qwen: asked for %d of %d layers", layers, cfg.NumLayers)
	}
	if maxTokens <= 0 {
		return nil, fmt.Errorf("qwen: maxTokens is %d", maxTokens)
	}
	if plan == nil {
		plan = DefaultGEMMPlan()
	}
	ok, err := canWMMA(dev)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("qwen: this device has no 16x16x16 fp16 cooperative matrix; the encoder graph needs one")
	}
	keep := make(map[int]bool, len(keepFP16))
	for _, l := range keepFP16 {
		if l < 0 || l >= layers {
			return nil, fmt.Errorf("qwen: keeping layer %d in fp16, but the encoder holds %d", l, layers)
		}
		keep[l] = true
	}
	if cfg.NumHeads%cfg.NumKVHeads != 0 {
		return nil, fmt.Errorf("qwen: %d heads do not divide into %d kv heads", cfg.NumHeads, cfg.NumKVHeads)
	}
	if cfg.HeadDim != headDim {
		return nil, fmt.Errorf("qwen: head dim %d, but the kernels are built for %d", cfg.HeadDim, headDim)
	}
	g := &GPUEncoder{
		dev:     dev,
		cfg:     cfg,
		ctl:     ctl,
		bank:    bank,
		keep:    keep,
		plan:    plan,
		pipes:   make(map[string]*vk.ComputePipeline),
		kernels: make(map[GEMMKernel]gemmVariant),
		tokens:  maxTokens,
		rows:    maxTokens,
		ldaDim:  cfg.HiddenSize + gemmPad,
		ldaQ:    cfg.NumHeads*cfg.HeadDim + gemmPad,
		ldaFFN:  cfg.IntermediateSize + gemmPad,
	}
	if err := g.chooseAttention(); err != nil {
		g.Destroy()
		return nil, err
	}
	// The run length is padded to the largest tile any dispatch covers: the
	// GEMM's BM, and the attention kernel's key block, which reads whole
	// blocks of the packed planes. One number serves both.
	//
	// Every rung is built and every rung reads the same fragment-tiled
	// weight, so the plan can be changed after construction (SetPlan) without
	// restaging 7 GB -- which is what makes the ladder in cmd/textenc one
	// load instead of seven. The arenas are therefore sized for the widest
	// tile in the table rather than for the plan.
	g.stagedLayout = 2
	if ctl.wrongBLayout {
		g.stagedLayout = 0
	}
	arenaAlign := g.attn.keyBlock()
	for _, v := range gemmVariants {
		if v.layout == kernelLayout {
			g.kernels[v.name] = v
			arenaAlign = max(arenaAlign, v.bm)
		}
	}
	if err := g.SetPlan(plan); err != nil {
		g.Destroy()
		return nil, err
	}
	// A caller that named a plan meant it; only the default schedules.
	g.AutoPlan = explicitPlan == nil
	g.arenaRows = roundUp(maxTokens, arenaAlign)

	if err := g.layoutWeights(layers, bankBytes); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.allocActivations(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.build(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.stageWeights(set, layers); err != nil {
		g.Destroy()
		return nil, err
	}
	return g, nil
}

// headDim is compiled into the pack and attention shaders.
const headDim = 128

func roundUp(n, m int) int { return (n + m - 1) / m * m }

func groups(n, per int) uint32 { return uint32((n + per - 1) / per) }
func (g *GPUEncoder) layoutWeights(layers, bankBytes int) error {
	c := g.cfg
	// fp32: the rotary table once, then four norm vectors per layer.
	ropeElems := 2 * g.tokens * (c.HeadDim / 2)
	total32 := ropeElems
	perLayer32 := 2*c.HiddenSize + 2*c.HeadDim

	shapes := g.projShapes()
	perProj := make(map[Proj]int, len(projOrder))
	perLayer16 := 0
	for _, r := range projOrder {
		// Sized for the larger of the two layouts, which differ only when
		// the wrongBLayout control is on: the natural [n, k+pad] carries the
		// §2.3 pad and the fragment tiling does not.
		n := max(bElems(shapes[r][0], shapes[r][1], g.stagedLayout),
			bElems(shapes[r][0], shapes[r][1], kernelLayout))
		perProj[r] = n
		perLayer16 += n
	}
	if perLayer16*2 > bankBytes {
		return fmt.Errorf("qwen: one layer's weights are %d MB and a bank holds %d MB",
			(perLayer16*2)>>20, bankBytes>>20)
	}
	perLayerQ := 0
	for _, r := range projOrder {
		perLayerQ += Q8Bytes(shapes[r][0], shapes[r][1])
	}

	g.w = make([]layerWeights, layers)
	var bankElems, qbankBytes []int
	cur := -1
	// Under BankQ8 every int8 layer is expanded into the same scratch, bank
	// 0, so they all share its fp16 offsets. A layer kept in fp16 packs
	// after it like any fp16 layer.
	var scratchOff map[Proj]uint32
	if g.bank == BankQ8 && len(g.keep) < layers {
		scratchOff = make(map[Proj]uint32, len(projOrder))
		bankElems, cur = []int{0}, 0
		for _, r := range projOrder {
			scratchOff[r] = uint32(bankElems[0])
			bankElems[0] += bElems(shapes[r][0], shapes[r][1], kernelLayout)
		}
	}
	for i := range g.w {
		w := layerWeights{bOff: make(map[Proj]uint32, len(projOrder))}
		w.attnNorm = uint32(total32)
		w.ffnNorm = w.attnNorm + uint32(c.HiddenSize)
		w.qNorm = w.ffnNorm + uint32(c.HiddenSize)
		w.kNorm = w.qNorm + uint32(c.HeadDim)
		total32 += perLayer32

		if g.bank == BankQ8 && !g.keep[i] {
			w.q8, w.bank, w.bOff = true, 0, scratchOff
			if len(qbankBytes) == 0 || qbankBytes[len(qbankBytes)-1]+perLayerQ > bankBytes {
				qbankBytes = append(qbankBytes, 0)
			}
			w.qbank = len(qbankBytes) - 1
			w.qOff = make(map[Proj]uint32, len(projOrder))
			for _, r := range projOrder {
				w.qOff[r] = uint32(qbankBytes[w.qbank])
				qbankBytes[w.qbank] += Q8Bytes(shapes[r][0], shapes[r][1])
			}
			g.w[i] = w
			continue
		}
		if cur < 0 || (bankElems[cur]+perLayer16)*2 > bankBytes {
			bankElems = append(bankElems, 0)
			cur = len(bankElems) - 1
		}
		w.bank = cur
		for _, r := range projOrder {
			w.bOff[r] = uint32(bankElems[cur])
			bankElems[cur] += perProj[r]
		}
		g.w[i] = w
	}
	for _, n := range qbankBytes {
		b, err := g.dev.NewBuffer(n)
		if err != nil {
			return fmt.Errorf("qwen: int8 weight bank %d (%d MB): %w", len(g.qbanks), n>>20, err)
		}
		g.qbanks = append(g.qbanks, b)
	}

	var err error
	if g.wbuf, err = g.dev.NewBuffer(total32 * 4); err != nil {
		return fmt.Errorf("qwen: fp32 weight arena (%d MB): %w", (total32*4)>>20, err)
	}
	g.wCos, g.wSin = 0, uint32(g.tokens*(c.HeadDim/2))
	for _, n := range bankElems {
		b, err := g.dev.NewBuffer(n * 2)
		if err != nil {
			return fmt.Errorf("qwen: fp16 weight bank %d (%d MB): %w", len(g.banks), (n*2)>>20, err)
		}
		g.banks = append(g.banks, b)
	}
	return nil
}

